class CSVProcessor {

    public init() {}

    public func read_csv(file_name: String): (ArrayList<String>, ArrayList<ArrayList<String>>) {
        let file_opt = open(file_name, mode: "r")
        if (file_opt == None<FileSystemHandle>) {
            return (ArrayList<String>(), ArrayList<ArrayList<String>>())
        }
        let file = file_opt.getOrThrow()
        let lines = ArrayList<String>()
        while (true) {
            let line_opt = file.readLine()
            if (line_opt == None<String>) {
                break
            }
            lines.add(line_opt.getOrThrow())
        }
        file.close()

        if (lines.size == 0) {
            return (ArrayList<String>(), ArrayList<ArrayList<String>>())
        }

        let title_line = lines[0]
        let titles = ArrayList<String>(title_line.split(","))
        for (i in 0..titles.size) {
            titles[i] = titles[i].trim()
        }

        let data = ArrayList<ArrayList<String>>()
        for (i in 1..lines.size) {
            let row = ArrayList<String>(lines[i].split(","))
            let cleaned_row = ArrayList<String>()
            for (cell in row) {
                cleaned_row.add(cell.trim())
            }
            data.add(cleaned_row)
        }

        return (titles, data)
    }

    public func write_csv(data: ArrayList<ArrayList<String>>, file_name: String): Int64 {
        let file_opt = open(file_name, mode: "w")
        if (file_opt == None<FileSystemHandle>) {
            return 0
        }
        let file = file_opt.getOrThrow()

        for (row in data) {
            let line_parts = ArrayList<String>()
            for (cell in row) {
                line_parts.add(cell)
            }
            let line = line_parts.join(",")
            file.write(line)
            file.write("\n")
        }

        file.close()
        return 1
    }

    public func process_csv_data(N: Int64, save_file_name: String): Int64 {
        let (titles, data) = read_csv(save_file_name)
        if (data.size == 0 && titles.size == 0) {
            return 0
        }

        // Create new data with only the Nth column, capitalized
        let processed_data = ArrayList<ArrayList<String>>()
        for (row in data) {
            if (N >= row.size || N < 0) {
                return 0
            }
            let cell = row[N]
            let upper_cell = cell.toUpper()
            let new_row = ArrayList<String>()
            new_row.add(upper_cell)
            processed_data.add(new_row)
        }

        // Derive new file name
        let last_dot = save_file_name.lastIndexOf(".")
        let base_name = if (last_dot == -1) {
                            save_file_name
                        } else {
                            save_file_name.substring(0, last_dot)
                        }
        let ext = if (last_dot == -1) { "" } else { save_file_name.substring(last_dot) }
        let new_file_name = "${base_name}_process${ext}"

        // Write to new file
        let result = write_csv(processed_data, new_file_name)
        return result
    }
}

import std.collection.HashMap
