import std.sort.*

class Interpolation {

    public static func interpolate_1d(x: ArrayList<Float64>, y: ArrayList<Float64>, x_interp: ArrayList<Float64>): ArrayList<Float64> {
        let n = x.size
        let m = x_interp.size
        var result = ArrayList<Float64>()

        // For each interpolation point
        for (i in 0..m) {
            let xi = x_interp[i]

            // Find the interval [x[j], x[j+1]] containing xi
            var j = 0
            while (j < n - 1 && x[j + 1] < xi) {
                j = j + 1
            }

            // Clamp to boundary if xi is out of range
            if (xi <= x[0]) {
                result.add(y[0])
            } else if (xi >= x[n - 1]) {
                result.add(y[n - 1])
            } else {
                // Linear interpolation
                let x0 = x[j]
                let x1 = x[j + 1]
                let y0 = y[j]
                let y1 = y[j + 1]
                let t = (xi - x0) / (x1 - x0)
                let yi = y0 + t * (y1 - y0)
                result.add(yi)
            }
        }

        return result
    }

    public static func interpolate_2d(x: ArrayList<Float64>, y: ArrayList<Float64>, z: ArrayList<ArrayList<Float64>>, x_interp: ArrayList<Float64>, y_interp: ArrayList<Float64>): ArrayList<Float64> {
        let nx = x.size
        let ny = y.size
        let m = x_interp.size
        var result = ArrayList<Float64>()

        for (idx in 0..m) {
            let xi = x_interp[idx]
            let yi = y_interp[idx]

            // Find x interval
            var i = 0
            while (i < nx - 1 && x[i + 1] < xi) {
                i = i + 1
            }
            if (i >= nx - 1) { i = nx - 2 }

            // Find y interval
            var j = 0
            while (j < ny - 1 && y[j + 1] < yi) {
                j = j + 1
            }
            if (j >= ny - 1) { j = ny - 2 }

            // Get grid points
            let x0 = x[i]
            let x1 = x[i + 1]
            let y0 = y[j]
            let y1 = y[j + 1]
            let q00 = z[i][j]
            let q10 = z[i + 1][j]
            let q01 = z[i][j + 1]
            let q11 = z[i + 1][j + 1]

            // Bilinear interpolation
            let dx = x1 - x0
            let dy = y1 - y0
            let tx = (xi - x0) / dx
            let ty = (yi - y0) / dy

            let top = q00 * (1.0 - tx) + q10 * tx
            let bottom = q01 * (1.0 - tx) + q11 * tx
            let zi = top * (1.0 - ty) + bottom * ty

            result.add(zi)
        }

        return result
    }
}

