class IpUtil {

    public static func is_valid_ipv4(ip_address: String): Bool {
        let parts = ip_address.split(".")
        if (parts.size != 4) {
            return false
        }
        for (part in parts) {
            if (part.size == 0 || part.size > 3) {
                return false
            }
            for (r in part.runes()) {
                if (r < r'0' || r > r'9') {
                    return false
                }
            }
            let num = part.toInt()
            if (num < 0 || num > 255) {
                return false
            }
            // Check leading zero: "0x", "00", etc. are invalid
            if (part.size > 1 && part[0] == '0') {
                return false
            }
        }
        return true
    }

    public static func is_valid_ipv6(ip_address: String): Bool {
        // Simplified check for valid IPv6 (standard compressed format allowed once)
        if (ip_address.size == 0 || ip_address.size > 39) {
            return false
        }
        let has_compressed = ip_address.contains("::")
        let double_colon_count = ip_address.split("::").size
        if (double_colon_count > 2) {
            return false
        }
        if (double_colon_count == 2 && ip_address.split("::").size != 2) {
            return false
        }

        let hex_parts = if (has_compressed) {
            ip_address.split("::")
        } else {
            [ip_address, ""]
        }

        let left = if (hex_parts.size > 0) { hex_parts[0] } else { "" }
        let right = if (hex_parts.size > 1) { hex_parts[1] } else { "" }

        let left_parts = if (left.size > 0) { left.split(":") } else { [] }
        let right_parts = if (right.size > 0) { right.split(":") } else { [] }

        let total_parts = left_parts.size + right_parts.size
        if (has_compressed) {
            if (total_parts > 8) {
                return false
            }
        } else {
            if (total_parts != 8) {
                return false
            }
        }

        let all_parts = ArrayList<String>()
        all_parts.addAll(left_parts)
        // Fill gap from ::
        let gap = 8 - total_parts
        for (i in 0..gap) {
            all_parts.add("")
        }
        all_parts.addAll(right_parts)

        for (part in all_parts) {
            if (part.size == 0) {
                continue
            }
            if (part.size > 4) {
                return false
            }
            for (r in part.runes()) {
                let c = r.toLower()
                if (!((c >= r'0' && c <= r'9') || (c >= r'a' && c <= r'f'))) {
                    return false
                }
            }
        }
        return true
    }

    public static func get_hostname(ip_address: String): Option<String> {
        if (!is_valid_ipv4(ip_address) && !is_valid_ipv6(ip_address)) {
            return None<String>
        }
        let hostname = gethostname(ip_address)
        if (hostname == "") {
            return None<String>
        }
        return Some<String>(hostname)
    }
}

