        this.resumes = ArrayList<Resume>()
    }

    public func post_job(job_title: String, company: String, requirements: ArrayList<String>): Unit {
        let job = JobListing(job_title, company, requirements)
        this.jobListings.add(job)
    }

    public func remove_job(job: JobListing): Unit {
        for (i in 0..this.jobListings.size) {
            if (this.jobListings[i] == job) {
                this.jobListings.remove(at: i)
                break
            }
        }
    }

    public func submit_resume(name: String, skills: ArrayList<String>, experience: String): Unit {
        let resume = Resume(name, skills, experience)
        this.resumes.add(resume)
    }

    public func withdraw_resume(resume: Resume): Unit {
        for (i in 0..this.resumes.size) {
            if (this.resumes[i] == resume) {
                this.resumes.remove(at: i)
                break
            }
        }
    }

    public func search_jobs(criteria: String): ArrayList<JobListing> {
        let result = ArrayList<JobListing>()
        for (job in this.jobListings) {
            for (requirement in job.requirements) {
                if (requirement == criteria) {
                    result.add(job)
                    break
                }
            }
        }
        return result
    }

    public func get_job_applicants(job: JobListing): ArrayList<Resume> {
        let result = ArrayList<Resume>()
        for (resume in this.resumes) {
            if (JobMarketplace.matches_requirements(resume, job.requirements)) {
                result.add(resume)
            }
        }
        return result
    }

    public static func matches_requirements(resume: Resume, requirements: ArrayList<String>): Bool {
        for (requirement in requirements) {
            var found = false
            for (skill in resume.skills) {
                if (skill == requirement) {
                    found = true
                    break
                }
            }
            if (!found) {
                return false
            }
        }
        return true
    }
}

import std.collection.ArrayList
import std.math.abs
import std.collection.HashMap

class KappaCalculator {

    public static func kappa(testData: ArrayList<ArrayList<Int64>>, k: Int64): Float64 {
        // Calculate Cohen's Kappa for a k x k confusion matrix
        // Assume testData is a k x k matrix: rows = true labels, cols = predicted labels

        var total: Int64 = 0
        var correct: Int64 = 0
        let expectedAgreementSums = ArrayList<Float64>()
        for (_ in 0..k) {
            expectedAgreementSums.add(0.0)
        }

        // Calculate total counts and correct predictions
        for (i in 0..k) {
            for (j in 0..k) {
                let val = testData[i][j]
                total += val
                if (i == j) {
                    correct += val
                }
                expectedAgreementSums[i] = expectedAgreementSums[i] + testData[i][j].to_Float64()
                expectedAgreementSums[j] = expectedAgreementSums[j] + testData[i][j].to_Float64()
            }
        }

        let actualAgreement = correct.to_Float64() / total.to_Float64()

        var expectedAgreement: Float64 = 0.0
        for (i in 0..k) {
            let p_i = expectedAgreementSums[i] / (2.0 * total.to_Float64())  // Each cell counted in row and col
            expectedAgreement += p_i * p_i
        }

        // Cohen's Kappa = (actual - expected) / (1 - expected)
        if (abs(1.0 - expectedAgreement) < 1e-9) {
            return 1.0
        } else {
            return (actualAgreement - expectedAgreement) / (1.0 - expectedAgreement)
        }
    }

    public static func fleiss_kappa(testData: ArrayList<ArrayList<Int64>>, N: Int64, k: Int64, n: Int64): Float64 {
        // Fleiss' Kappa for N subjects rated by n raters into k categories

        var totalRatings: Float64 = 0.0
        var p_bar_sum: Float64 = 0.0
        var p_j = ArrayList<Float64>()
        for (_ in 0..k) {
            p_j.add(0.0)
        }

        // Step 1: Compute P_i for each subject (i = 0 to N-1)
        for (i in 0..N) {
            var sum_square: Float64 = 0.0
            for (j in 0..k) {
                let count_ij = testData[i][j].to_Float64()
                sum_square += count_ij * count_ij
                p_j[j] += count_ij
            }
            let p_i = (sum_square - n.to_Float64()) / (n.to_Float64() * (n.to_Float64() - 1.0))
            p_bar_sum += p_i
        }

        // Average P = P_bar
        let p_bar = p_bar_sum / N.to_Float64()

        // Step 2: Compute overall category proportions (p_j), then Pe_bar
        totalRatings = n.to_Float64() * N.to_Float64()
        var pe_bar: Float64 = 0.0
        for (j in 0..k) {
            let pj = p_j[j] / totalRatings
            pe_bar += pj * pj
        }

        // Fleiss' Kappa = (P_bar - Pe_bar) / (1 - Pe_bar)
        if (abs(1.0 - pe_bar) < 1e-9) {
            return 1.0
        } else {
            return (p_bar - pe_bar) / (1.0 - pe_bar)
        }
    }
}

import std.collection.ArrayList
import std.regex.Regex

class LongestWord {
    let word_list: ArrayList<String>

    public init() {
        this.word_list = ArrayList<String>()
    }

    public func add_word(word: String): Unit {
        this.word_list.add(word)
    }

    public func find_longest_word(sentence: String): String {
        if (this.word_list.size == 0) {
            return ""
        }

        let cleaned = Regex("[^a-zA-Z\\s]").replace_all(sentence, "")
        let words = cleaned.split(" ")

        var longest: String = ""

        for (word in words) {
            let trimmed = word.trim()
            if (this.word_list.contains(trimmed) && trimmed.size > longest.size) {
                longest = trimmed
            }
        }

        return longest
    }
}

