class MetricsCalculator2 {

    public init() {}

    public static func mrr(data: Any): (Float64, ArrayList<Float64>) {
        let results = ArrayList<Float64>()

        // Check if data is a single tuple
        if (data is (ArrayList<Int64>, Int64)) {
            let (ranks, total) = data as (ArrayList<Int64>, Int64)
            let rr = computeReciprocalRank(ranks)
            results.add(rr)
        } 
        // Check if data is a list of tuples
        else if (data is ArrayList<(ArrayList<Int64>, Int64)>) {
            let list = data as ArrayList<(ArrayList<Int64>, Int64)>
            for (item in 0..list.size) {
                let (ranks, total) = list[item]
                let rr = computeReciprocalRank(ranks)
                results.add(rr)
            }
        }

        let avg = computeMean(results)
        return (avg, results)
    }

    private static func computeReciprocalRank(ranks: ArrayList<Int64>): Float64 {
        for (i in 0..ranks.size) {
            if (ranks[i] == 1) {
                return 1.0 / (i + 1) as Float64
            }
        }
        return 0.0
    }

    public static func map(data: Any): (Float64, ArrayList<Float64>) {
        let results = ArrayList<Float64>()

        // Check if data is a single tuple
        if (data is (ArrayList<Int64>, Int64)) {
            let (ranks, total) = data as (ArrayList<Int64>, Int64)
            let ap = computeAveragePrecision(ranks, total)
            results.add(ap)
        } 
        // Check if data is a list of tuples
        else if (data is ArrayList<(ArrayList<Int64>, Int64)>) {
            let list = data as ArrayList<(ArrayList<Int64>, Int64)>
            for (item in 0..list.size) {
                let (ranks, total) = list[item]
                let ap = computeAveragePrecision(ranks, total)
                results.add(ap)
            }
        }

        let avg = computeMean(results)
        return (avg, results)
    }

    private static func computeAveragePrecision(ranks: ArrayList<Int64>, total: Int64): Float64 {
        let correct = ArrayList<Int64>()
        let mut count = 0
        for (i in 0..ranks.size) {
            if (ranks[i] == 1) {
                count += 1
            }
            correct.add(count)
        }

        let mut sum = 0.0
        let mut retrieved = 0
        for (i in 0..ranks.size) {
            if (ranks[i] == 1) {
                retrieved += 1
                sum += correct[i] * 1.0 / (i + 1) as Float64
            }
        }

        if (retrieved == 0) {
            return 0.0
        }

        return sum / total as Float64
    }

    private static func computeMean(list: ArrayList<Float64>): Float64 {
        let mut sum = 0.0
        for (i in 0..list.size) {
            sum += list[i]
        }
        if (list.size == 0) {
            return 0.0
        }
        return sum / list.size as Float64
    }
}

import std.collection.*
import std.random.Random
import std.convert.Parsable

class MinesweeperGame {

    let n: Int64
    let k: Int64
    var minesweeper_map: ArrayList<ArrayList<String>>
    var player_map: ArrayList<ArrayList<String>>
    var score: Int64

    public init(n: Int64, k: Int64) {
        this.n = n
        this.k = k
        this.minesweeper_map = generate_mine_sweeper_map(n, k)
        this.player_map = generate_playerMap(n)
        this.score = 0
    }

    public static func generate_mine_sweeper_map(n: Int64, k: Int64): ArrayList<ArrayList<String>> {
        let map = ArrayList<ArrayList<String>>()
        for (i in 0..n) {
            let row = ArrayList<String>()
            for (j in 0..n) {
                row.add("0")
            }
            map.add(row)
        }

        let rand = Random()
        var mines_placed = 0
        while (mines_placed < k) {
            let x = rand.next() % n
            let y = rand.next() % n
            if (map[x][y] != "X") {
                map[x][y] = "X"
                mines_placed += 1

                for (dx in -1..2) {
                    for (dy in -1..2) {
                        let nx = x + dx
                        let ny = y + dy
                        if (nx >= 0 && nx < n && ny >= 0 && ny < n && map[nx][ny] != "X") {
                            let val = Int64.parse(map[nx][ny]) ?? 0
                            map[nx][ny] = (val + 1).toString()
                        }
                    }
                }
            }
        }
        return map
    }

    public static func generate_playerMap(n: Int64): ArrayList<ArrayList<String>> {
        let map = ArrayList<ArrayList<String>>()
        for (i in 0..n) {
            let row = ArrayList<String>()
            for (j in 0..n) {
                row.add("-")
            }
            map.add(row)
        }
        return map
    }

    public func check_won(map: ArrayList<ArrayList<String>>): Bool {
        for (i in 0..n) {
            for (j in 0..n) {
                if (map[i][j] == "-") {
                    if (minesweeper_map[i][j] != "X") {
                        return false
                    }
                }
            }
        }
        return true
    }

    public func sweep(x: Int64, y: Int64): Any {
        if (x < 0 || x >= n || y < 0 || y >= n) {
            return player_map
        }

        if (player_map[x][y] != "-") {
            return player_map
        }

        if (minesweeper_map[x][y] == "X") {
            return false
        }

        player_map[x][y] = minesweeper_map[x][y]

        if (player_map[x][y] == "0") {
            for (dx in -1..2) {
                for (dy in -1..2) {
                    let nx = x + dx
                    let ny = y + dy
                    if (nx != x || ny != y) {
                        sweep(nx, ny)
                    }
                }
            }
        }

        if (check_won(player_map)) {
            return true
        }

        return player_map
    }
}

import std.collection.ArrayList
import std.collection.HashMap
import std.time.DateTime
import std.math.abs

class MovieBookingSystem {

    let movies: ArrayList<HashMap<String, Any>>

    public init() {
        movies = ArrayList<HashMap<String, Any>>()
    }

    public func add_movie(name: String, price: Float64, start_time: String, end_time: String, n: Int64): Unit {
        let startTime = DateTime.parse(start_time, "yyyy/MM/dd HH:mm")
        let endTime = DateTime.parse(end_time, "yyyy/MM/dd HH:mm")

        let seats = ArrayList<ArrayList<Int64>>()
        for (i in 0..n) {
            let row = ArrayList<Int64>()
            for (j in 0..n) {
                row.add(0)
            }
            seats.add(row)
        }

        let movie = HashMap<String, Any>([
            ("name", name),
            ("price", price),
            ("start_time", startTime),
            ("end_time", endTime),
            ("seats", seats)
        ])

        movies.add(movie)
    }

    public func book_ticket(name: String, seats_to_book: ArrayList<ArrayList<Int64>>): String {
        for (movie in movies) {
            let movieName: String = movie["name"]
            if (movieName == name) {
                let seats: ArrayList<ArrayList<Int64>> = movie["seats"]
                for (seat in seats_to_book) {
                    let row = seat[0]
                    let col = seat[1]
                    if (row < 0 || row >= seats.size || col < 0 || col >= seats[0].size) {
                        return "Booking failed."
                    }
                    if (seats[row][col] == 1) {
                        return "Booking failed."
                    }
                }
                for (seat in seats_to_book) {
                    let row = seat[0]
                    let col = seat[1]
                    seats[row][col] = 1
                }
                return "Booking success."
            }
        }
        return "Movie not found."
    }

    public func available_movies(start_time: String, end_time: String): ArrayList<String> {
        let query_start = DateTime.parse(start_time, "yyyy/MM/dd HH:mm")
        let query_end = DateTime.parse(end_time, "yyyy/MM/dd HH:mm")

        let result = ArrayList<String>()
        for (movie in movies) {
            let movie_start: DateTime = movie["start_time"]
            let movie_end: DateTime = movie["end_time"]
            if (movie_start >= query_start && movie_end <= query_end) {
                let name: String = movie["name"]
                result.add(name)
            }
        }
        return result
    }
}

import std.random.Random
import std.collection.ArrayList

class MusicPlayer {

    /*
    This is a class as a music player that provides to play, stop, add songs, remove songs, set volume, shuffle, and switch to the next or previous song.
    */

    var playlist: ArrayList<String>
    var current_song: Option<String>
    var volume: Int64

    public init() {
        /*
        Initializes the music player with an empty playlist, no current song, and a default volume of 50.
        */
        this.playlist = ArrayList<String>()
        this.current_song = None
        this.volume = 50
    }

    public func add_song(song: String): Unit {
        /*
        Adds a song to the playlist.
        :param song: The song to add to the playlist, String.
        >>> musicPlayer = MusicPlayer()
        >>> musicPlayer.add_song("song1")
        >>> musicPlayer.playlist
        ['song1']

        */
        this.playlist.add(song)
    }

    public func remove_song(song: String): Unit {
        /*
        Removes a song from the playlist.
        :param song: The song to remove from the playlist, String.
        >>> musicPlayer = MusicPlayer()
        >>> musicPlayer.playlist = ArrayList<String>(["song1", "song2"])
        >>> musicPlayer.remove_song("song1")
        >>> musicPlayer.playlist
        ['song2']

        */
        if (this.playlist.contains(song)) {
            this.playlist.remove(song)
        }
    }

    public func play(): Option<String> {
        /*
        Plays the current song in the playlist.
        :return: The current song in the playlist, or "False" if there is no current song, or None if the playlist is empty, Option<String>.
        >>> musicPlayer = MusicPlayer()
        >>> musicPlayer.playlist = ArrayList<String>(["song1", "song2"])
        >>> musicPlayer.current_song = "song1"
        >>> musicPlayer.play()
        'song1'

        */
        if (this.playlist.size == 0) {
            return None
        }
        if (this.current_song.isSome()) {
            return this.current_song
        } else {
            if (this.playlist.size > 0) {
                this.current_song = Some(this.playlist[0])
                return this.current_song
            } else {
                return None
            }
        }
    }

    public func stop(): Bool {
        /*
        Stops the current song in the playlist.
        :return: true if the current song was stopped, false if there was no current song.
        >>> musicPlayer = MusicPlayer()
        >>> musicPlayer.playlist = ArrayList<String>(["song1", "song2"])
        >>> musicPlayer.current_song = "song1"
        >>> musicPlayer.stop()
        true

        */
        if (this.current_song.isSome()) {
            this.current_song = None
            return true
        } else {
            return false
        }
    }

    public func switch_song(): Bool {
        /*
        Switches to the next song in the playlist.
        :return: true if the next song was switched to, false if there was no next song.
        >>> musicPlayer = MusicPlayer()
        >>> musicPlayer.playlist = ArrayList<String>(["song1", "song2"])
        >>> musicPlayer.current_song = "song1"
        >>> musicPlayer.switch_song()
        true

        */
        if (this.current_song.isNone() || this.playlist.size == 0) {
            return false
        }

        let current = this.current_song.getOrThrow()
        for (i in 0..this.playlist.size) {
            if (this.playlist[i] == current) {
                if (i + 1 < this.playlist.size) {
                    this.current_song = Some(this.playlist[i + 1])
                    return true
                } else {
                    return false
                }
            }
        }
        return false
    }

    public func previous_song(): Bool {
        /*
        Switches to the previous song in the playlist.
        :return: true if the previous song was switched to, false if there was no previous song.
        >>> musicPlayer = MusicPlayer()
        >>> musicPlayer.playlist = ArrayList<String>(["song1", "song2"])
        >>> musicPlayer.current_song = "song2"
        >>> musicPlayer.previous_song()
        true

        */
        if (this.current_song.isNone() || this.playlist.size == 0) {
            return false
        }

        let current = this.current_song.getOrThrow()
        for (i in 0..this.playlist.size) {
            if (this.playlist[i] == current) {
                if (i > 0) {
                    this.current_song = Some(this.playlist[i - 1])
                    return true
                } else {
                    return false
                }
            }
        }
        return false
    }

    public func set_volume(volume: Int64): Bool {
        /*
        Sets the volume of the music player, if the volume is between 0 and 100 is valid.
        :param volume: The volume to set the music player to, Int64.
        :return: true if the volume was set, false if the volume was invalid.
        >>> musicPlayer = MusicPlayer()
        >>> musicPlayer.set_volume(50)
        true
        >>> musicPlayer.volume
        50

        */
        if (volume >= 0 && volume <= 100) {
            this.volume = volume
            return true
        } else {
            return false
        }
    }

    public func shuffle(): Bool {
        /*
        Shuffles the playlist.
        :return: true if the playlist was shuffled, false if the playlist was empty.
        >>> musicPlayer = MusicPlayer()
        >>> musicPlayer.playlist = ArrayList<String>(["song1", "song2"])
        >>> musicPlayer.shuffle()
        true

        */
        if (this.playlist.size == 0) {
            return false
        }

        // Fisher–Yates shuffle
        for (i in (this.playlist.size - 1)..0:-1) {
            let j = Random.nextI64(0, i)
            let temp = this.playlist[i]
            this.playlist[i] = this.playlist[j]
            this.playlist[j] = temp
        }
        return true
    }
}

import std.collection.ArrayList
import std.collection.*

class NLPDataProcessor {

    public func construct_stop_word_list(): ArrayList<String> {
        let stop_words = ArrayList<String>(["a", "an", "the"])
        return stop_words
    }

    public func remove_stop_words(string_list: ArrayList<String>, stop_word_list: ArrayList<String>): ArrayList<ArrayList<String>> {
        let result = ArrayList<ArrayList<String>>()
        let stop_word_set = HashSet<String>(stop_word_list)

        for (s in 0..string_list.size) {
            let words = string_list[s].split(" ")
            let filtered_words = ArrayList<String>()
            for (word in 0..words.size) {
                let cleaned_word = words[word].lower()
                if (stop_word_set.contains(cleaned_word) == false) {
                    filtered_words.add(words[word])
                }
            }
            result.add(filtered_words)
        }

        return result
    }

    public func process(string_list: ArrayList<String>): ArrayList<ArrayList<String>> {
        let stop_word_list = construct_stop_word_list()
        return remove_stop_words(string_list, stop_word_list)
    }
}

import std.collection.ArrayList
