import std.regex.Regex
import std.sort.sort
import std.unicode.UnicodeStringExtension

class NLPDataProcessor2 {

    public func process_data(string_list: ArrayList<String>): ArrayList<ArrayList<String>> {
        let words_list = ArrayList<ArrayList<String>>()
        let pattern = Regex("[^a-zA-Z\\s]")

        for (s in 0..string_list.size) {
            let cleaned = pattern.replace_all(string_list[s], with: "").to_lower()
            let words = cleaned.split(" ")
            let word_array = ArrayList<String>()

            for (word in 0..words.size) {
                let w = words[word].strip()
                if (w.size > 0) {
                    word_array.add(w)
                }
            }

            words_list.add(word_array)
        }

        return words_list
    }

    public func calculate_word_frequency(words_list: ArrayList<ArrayList<String>>): HashMap<String, Int64> {
        let freq_map = HashMap<String, Int64>()

        for (word_list in 0..words_list.size) {
            for (word in 0..words_list[word_list].size) {
                let w = words_list[word_list][word]
                if (freq_map.contains(w)) {
                    freq_map[w] = freq_map[w] + 1
                } else {
                    freq_map.add(w, 1)
                }
            }
        }

        // Sort by frequency descending and return full map (sorting used in process)
        return freq_map
    }

    public func process(string_list: ArrayList<String>): HashMap<String, Int64> {
        let words_list = process_data(string_list)
        let freq_map = calculate_word_frequency(words_list)

        // Convert to array for sorting
        let entries = ArrayList<(String, Int64)>()
        for (k in freq_map.keys()) {
            entries.add((k, freq_map[k]!!))
        }

        // Sort by frequency descending
        let cmp = {(a: (String, Int64), b: (String, Int64)) => b[1] < a[1]}
        sort(entries, lessThan: cmp)

        // Take top 5
        let result = HashMap<String, Int64>()
        let limit = if (entries.size < 5) { entries.size } else { 5 }
        for (i in 0..limit) {
            result.add(entries[i][0], entries[i][1])
        }

        return result
    }
}

import std.convert.Formattable
import std.convert.Parsable
import std.convert.RadixConvertible

class NumberConverter {

    public static func decimal_to_binary(decimal_num: Int64): String {
        if (decimal_num == 0) {
            return "0"
        }
        let is_negative = decimal_num < 0
        var num = if (is_negative) { -decimal_num } else { decimal_num }
        var result = ""
        while (num > 0) {
            result = (num % 2).toString() + result
            num = num // 2
        }
        return result
    }

    public static func binary_to_decimal(binary_num: String): Int64 {
        var result: Int64 = 0
        for (i in 0..binary_num.size) {
            let c = binary_num[i]
            result = result * 2 + (c == '1' ? 1 : 0)
        }
        return result
    }

    public static func decimal_to_octal(decimal_num: Int64): String {
        if (decimal_num == 0) {
            return "0"
        }
        let is_negative = decimal_num < 0
        var num = if (is_negative) { -decimal_num } else { decimal_num }
        var result = ""
        while (num > 0) {
            result = (num % 8).toString() + result
            num = num // 8
        }
        return result
    }

    public static func octal_to_decimal(octal_num: String): Int64 {
        var result: Int64 = 0
        for (i in 0..octal_num.size) {
            let c = octal_num[i]
            result = result * 8 + (c - '0')
        }
        return result
    }

    public static func decimal_to_hex(decimal_num: Int64): String {
        if (decimal_num == 0) {
            return "0"
        }
        let is_negative = decimal_num < 0
        var num = if (is_negative) { -decimal_num } else { decimal_num }
        let digits = "0123456789abcdef"
        var result = ""
        while (num > 0) {
            result = digits[num % 16] + result
            num = num // 16
        }
        return result
    }

    public static func hex_to_decimal(hex_num: String): Int64 {
        var result: Int64 = 0
        for (i in 0..hex_num.size) {
            let c = hex_num[i]
            let val = if (c >= '0' && c <= '9') { c - '0' }
                     else if (c >= 'a' && c <= 'f') { c - 'a' + 10 }
                     else { c - 'A' + 10 }
            result = result * 16 + val
        }
        return result
    }
}

import std.convert.Parsable
import std.unicode.UnicodeStringExtension

class NumberWordFormatter {

    let NUMBER: Array<String>
    let NUMBER_TEEN: Array<String>
    let NUMBER_TEN: Array<String>
    let NUMBER_MORE: Array<String>
    let NUMBER_SUFFIX: Array<String>

    public init() {
        this.NUMBER = ["", "ONE", "TWO", "THREE", "FOUR", "FIVE", "SIX", "SEVEN", "EIGHT", "NINE"]
        this.NUMBER_TEEN = ["TEN", "ELEVEN", "TWELVE", "THIRTEEN", "FOURTEEN", "FIFTEEN", "SIXTEEN", "SEVENTEEN",
                            "EIGHTEEN", "NINETEEN"]
        this.NUMBER_TEN = ["TEN", "TWENTY", "THIRTY", "FORTY", "FIFTY", "SIXTY", "SEVENTY", "EIGHTY", "NINETY"]
        this.NUMBER_MORE = ["", "THOUSAND", "MILLION", "BILLION"]
        this.NUMBER_SUFFIX = ["k", "w", "", "m", "", "", "b", "", "", "t", "", "", "p", "", "", "e"]
    }

    public func format(x: Option<String>): String {
        match (x) {
            case Some(value) => format_string(value)
            case None(String) => "INVALID INPUT"
        }
    }

    public func format_string(x: String): String {
        let digits = x.runes().filter({ r: Rune => r.isDigit() }).collect()
        let numStr = String(digits)
        if (numStr.size == 0) {
            return "INVALID INPUT"
        }

        if (numStr.size == 1 && numStr[0] == '0') {
            return "ZERO ONLY"
        }

        var result: String = ""
        var length = numStr.size
        var groups = ArrayList<String>()

        // Split number into groups of three digits from right to left
        var i = length
        while (i > 0) {
            let start = if (i >= 3) { i - 3 } else { 0 }
            groups.add(numStr[start..i])
            i = start
        }

        // Process each group
        for (idx in 0..groups.size) {
            let group = groups[groups.size - idx - 1]
            let groupWord = trans_three(group)
            if (groupWord != "") {
                if (result != "") {
                    result = result + " "
                }
                result = result + groupWord
                let suffix = parse_more(groups.size - idx - 1)
                if (suffix != "") {
                    result = result + " " + suffix
                }
            }
        }

        result = result + " ONLY"
        return result
    }

    public func trans_two(s: String): String {
        if (s.size == 1) {
            return NUMBER[s[0] - '0']
        }
        if (s[0] == '0') {
            return NUMBER[s[1] - '0']
        }
        if (s[0] == '1') {
            return NUMBER_TEEN[s[1] - '0']
        }
        let ten = NUMBER_TEN[s[0] - '0' - 1]
        let one = NUMBER[s[1] - '0']
        return if (one != "") { ten + " " + one } else { ten }
    }

    public func trans_three(s: String): String {
        if (s.size == 1) {
            return NUMBER[s[0] - '0']
        }
        if (s.size == 2) {
            return trans_two(s)
        }
        let hundredDigit = s[0] - '0'
        let rest = s[1..3]
        let hundredPart = if (hundredDigit > 0) { NUMBER[hundredDigit] + " HUNDRED" } else { "" }
        let restPart = trans_two(rest)
        return if (restPart != "") {
            if (hundredPart != "") {
                hundredPart + " AND " + restPart
            } else {
                restPart
            }
        } else {
            hundredPart
        }
    }

    public func parse_more(i: Int64): String {
        if (i < 0 || i >= NUMBER_MORE.size) {
            return ""
        }
        return NUMBER_MORE[i]
    }
}

import std.collection.ArrayList
import std.convert.RadixConvertible

class NumericEntityUnescaper {

    public init() {}

    public func replace(string: String): String {
        let runes = string.runes().toArrayList()
        let result = ArrayList<Rune>()
        var i = 0

        while (i < runes.size) {
            let rune = runes[i]
            if (rune == r'&' && i + 1 < runes.size && runes[i + 1] == r'#') {
                // Check for hex or decimal
                var j = i + 2
                var is_hex = false
                if (j < runes.size && (runes[j] == r'x' || runes[j] == r'X')) {
                    is_hex = true
                    j += 1
                }

                var num_str = ArrayList<Rune>()
                var ended = false
                while (j < runes.size) {
                    let c = runes[j]
                    if (c == r';') {
                        ended = true
                        break
                    }
                    if (is_hex && !NumericEntityUnescaper.is_hex_char(c)) {
                        break
                    }
                    if (!is_hex && (c < r'0' || c > r'9')) {
                        break
                    }
                    num_str.add(c)
                    j += 1
                }

                if (ended && num_str.size > 0) {
                    let num_string = String(num_str)
                    let code_point: ?Int64 = if (is_hex) {
                        Int64.fromRadix(num_string, radix: 16) ?? None<Int64>
                    } else {
                        Int64.fromRadix(num_string, radix: 10) ?? None<Int64>
                    }

                    if (code_point != None<Int64>) {
                        let cp = code_point ?? 0
                        if (cp >= 0 && cp <= 0x10FFFF) {
                            result.add(rune(cp))
                            i = j + 1  // skip to after ';'
                            continue
                        }
                    }
                }
            }

            result.add(rune)
            i += 1
        }

        return String(result)
    }

    public static func is_hex_char(char: Rune): Bool {
        return (char >= r'0' && char <= r'9') ||
               (char >= r'a' && char <= r'f') ||
               (char >= r'A' && char <= r'F')
    }
}

