import std.collection.ArrayList

class RegexUtils {

    public func match_regex(pattern: String, text: String): Bool {
        let regex = Regex(pattern)
        return regex.isMatch(text)
    }

    public func findall(pattern: String, text: String): ArrayList<String> {
        let regex = Regex(pattern)
        let matches = regex.findAll(text)
        let result = ArrayList<String>()
        for (m in matches) {
            result.add(m.value)
        }
        return result
    }

    public func split(pattern: String, text: String): ArrayList<String> {
        let regex = Regex(pattern)
        return regex.split(text)
    }

    public func sub(pattern: String, replacement: String, text: String): String {
        let regex = Regex(pattern)
        return regex.replace(text, with: replacement)
    }

    public func generate_email_pattern(): String {
        return #'\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Z|a-z]{2,}\b'#
    }

    public func generate_phone_number_pattern(): String {
        return #'\b\d{3}-\d{3}-\d{4}\b'#
    }

    public func generate_split_sentences_pattern(): String {
        return #'[.!?][\s]{1,2}(?=[A-Z])'#
    }

    public func split_sentences(text: String): ArrayList<String> {
        let pattern = self.generate_split_sentences_pattern()
        let parts = self.split(pattern, text)
        let result = ArrayList<String>()
        let n = parts.size
        for (i in 0..n) {
            let part = parts[i]
            if (i < n - 1) {
                // Remove trailing punctuation and whitespace
                let cleaned = Regex(#'[.!?]+\s*$'#).replace(part, with: "")
                result.add(cleaned)
            } else {
                // Last part may not have a sentence ending, keep as-is
                result.add(part)
            }
        }
        return result
    }

    public func validate_phone_number(phone_number: String): Bool {
        let pattern = self.generate_phone_number_pattern()
        return self.match_regex(pattern, phone_number)
    }

    public func extract_email(text: String): ArrayList<String> {
        let pattern = self.generate_email_pattern()
        return self.findall(pattern, text)
    }
}

class RPGCharacter {

    let name: String
    var hp: Int64
    var attack_power: Int64
    var defense: Int64
    var level: Int64
    var exp: Int64

    public init(name: String, hp: Int64, attack_power: Int64, defense: Int64, level!: Int64 = 1) {
        this.name = name
        this.hp = hp
        this.attack_power = attack_power
        this.defense = defense
        this.level = level
        this.exp = 0
    }

    public func attack(other_character: RPGCharacter): Unit {
        let damage = this.attack_power - other_character.defense
        let actual_damage = if (damage > 0) { damage } else { 0 }
        other_character.hp = other_character.hp - actual_damage
    }

    public func heal(): Int64 {
        this.hp = if (this.hp + 10 > 100) { 100 } else { this.hp + 10 }
        return this.hp
    }

    public func gain_exp(amount: Int64): Unit {
        var remaining_exp = amount
        while (remaining_exp > 0) {
            let exp_needed = this.level * 100
            if (this.exp + remaining_exp >= exp_needed) {
                remaining_exp = remaining_exp - (exp_needed - this.exp)
                this.level_up()
            } else {
                this.exp = this.exp + remaining_exp
                remaining_exp = 0
            }
        }
    }

    public func level_up(): (Int64, Int64, Int64, Int64) {
        if (this.level >= 100) {
            return (this.level, this.hp, this.attack_power, this.defense)
        }
        this.level = this.level + 1
        this.hp = this.hp + 20
        this.attack_power = this.attack_power + 5
        this.defense = this.defense + 5
        this.exp = 0
        return (this.level, this.hp, this.attack_power, this.defense)
    }

    public func is_alive(): Bool {
        return this.hp > 0
    }
}

import std.collection.ArrayList
import std.collection.HashMap

class Server {

    /*
    This is a class as a server, which handles a white list, message sending and receiving, and information display.
    */

    let white_list: ArrayList<Int64>
    let send_struct: HashMap<String, Any>
    let receive_struct: HashMap<String, Any>

    public init() {
        /*
        Initialize the whitelist as an empty list, and initialize the sending and receiving information as an empty map.
        */
        this.white_list = ArrayList<Int64>()
        this.send_struct = HashMap<String, Any>()
        this.receive_struct = HashMap<String, Any>()
    }

    public func add_white_list(addr: Int64): Option<ArrayList<Int64>> {
        /*
        Add an address to the whitelist and do nothing if it already exists
        :param addr: Int64, address to be added
        :return: new whitelist, return None if the address already exists
        >>> server = Server()
        >>> server.add_white_list(88)
        [88]
        */
        if (this.white_list.contains(addr)) {
            return None<ArrayList<Int64>>
        }
        this.white_list.add(addr)
        return Some<ArrayList<Int64>>(this.white_list)
    }

    public func del_white_list(addr: Int64): Option<ArrayList<Int64>> {
        /*
        Remove an address from the whitelist and do nothing if it does not exist
        :param addr: Int64, address to be deleted
        :return: new whitelist, return None if the address does not exist
        >>> server.add_white_list(88)
        >>> server.del_white_list(88)
        []
        */
        if (!this.white_list.contains(addr)) {
            return None<ArrayList<Int64>>
        }
        this.white_list.remove(addr)
        return Some<ArrayList<Int64>>(this.white_list)
    }

    public func recv(info: HashMap<String, Any>): Any {
        /*
        Receive information containing address and content. If the address is on the whitelist, receive the content; otherwise, do not receive it
        :param info: HashMap<String, Any>, information dictionary containing address and content
        :return: if successfully received, return the content of the information; otherwise, return false
        >>> server.recv(HashMap<String, Any>([("addr",88),("content","abc")]))
        abc
        */
        let addr = info["addr"] ?? false
        if (addr == false || !isInWhiteList(addr as Int64)) {
            return false
        }
        this.receive_struct = info
        return info["content"] ?? false
    }

    public func send(info: HashMap<String, Any>): Option<String> {
        /*
        Send information containing address and content
        :param info: HashMap<String, Any>, information dictionary containing address and content
        :return: if successfully sent, return None; otherwise, return "info structure is not correct"
        >>> server.send(HashMap<String, Any>([("addr",66),("content","ABC")]))
        None
        this.send_struct = HashMap<String, Any>([("addr",66),("content","ABC")])
        */
        if (!info.contains("addr") || !info.contains("content")) {
            return Some<String>("info structure is not correct")
        }
        this.send_struct = info
        return None<String>
    }

    public func show(type_struct: String): Option<HashMap<String, Any>> {
        /*
        Returns struct of the specified type
        :param type: String, the type of struct to be returned, which can be 'send' or 'receive'
        :return: if type is equal to 'send' or 'receive', return the corresponding struct; otherwise, return None
        >>> server.recv(HashMap<String, Any>([("addr",88),("content","abc")]))
        >>> server.send(HashMap<String, Any>([("addr",66),("content","ABC")]))
        >>> server.show("send")
        {"addr":66,"content":"ABC"}
        */
        if (type_struct == "send") {
            return Some<HashMap<String, Any>>(this.send_struct)
        } else if (type_struct == "receive") {
            return Some<HashMap<String, Any>>(this.receive_struct)
        } else {
            return None<HashMap<String, Any>>
        }
    }

    private func isInWhiteList(addr: Int64): Bool {
        return this.white_list.contains(addr)
    }
}

import std.collection.HashMap
import std.math.abs

class Item <: Equatable<Item> {

    var price: Float64
    var quantity: Int64

    public init(price: Float64, quantity: Int64) {
        this.price = price
        this.quantity = quantity
    }

    public override operator func != (that: Item): Bool {
        return this.price != that.price || this.quantity != that.quantity
    }

    public override operator func == (that: Item): Bool {
        return this.price == that.price && this.quantity == that.quantity
    }
}

class ShoppingCart {

    let items: HashMap<String, Item>

    public init() {
        items = HashMap<String, Item>()
    }

    public func add_item(item: String, price: Float64, quantity!: Int64 = 1): Unit {
        if (items.contains(item)) {
            var existing_item = items[item]!
            existing_item.quantity += quantity
            items.add(item, existing_item)
        } else {
            items.add(item, Item(price, quantity))
        }
    }

    public func remove_item(item: String, quantity!: Int64 = 1): Unit {
        if (!items.contains(item)) {
            return
        }
        var existing_item = items[item]!
        if (quantity >= existing_item.quantity) {
            items.remove(item)
        } else {
            existing_item.quantity -= quantity
            items.add(item, existing_item)
        }
    }

    public func view_items(): HashMap<String, Item> {
        return items
    }

    public func total_price(): Float64 {
        var total: Float64 = 0.0
        for (key in items.keys()) {
            let item = items[key]!
            total += item.price * item.quantity.cast<Float64>()
        }
        return total
    }
}

import std.collection.HashMap
import std.collection.ArrayList

class SignInSystem {

    /*
    This is a class as sigin in system, including adding users, signing in/out, checking sign-in status, and retrieving signed-in/not signed-in users.
    */

    let users: HashMap<String, Bool>

    public init() {
        /*
        Initialize the sign-in system.
        */
        users = HashMap<String, Bool>()
    }

    public func add_user(username: String): Bool {
        /*
        Add a user to the sign-in system if the user wasn't in the this.users.
        And the initial state is false.
        :param username: String, the username to be added.
        :return: Bool, true if the user is added successfully, false if the user already exists.
        >>> signInSystem.add_user("mike")
        true
        >>> signInSystem.add_user("mike")
        false
        */
        if (users.contains(username)) {
            return false
        }
        users.add(username, false)
        return true
    }

    public func sign_in(username: String): Bool {
        /*
        Sign in a user if the user was in the this.users and change the state to true.
        :param username: String, the username to be signed in.
        :return: Bool, true if the user is signed in successfully, false if the user does not exist.
        >>> signInSystem.sign_in("mike")
        true
        >>> signInSystem.sign_in("mik")
        false
        */
        if (!users.contains(username)) {
            return false
        }
        users[username] = true
        return true
    }

    public func check_sign_in(username: String): Bool {
        /*
        Check if a user is signed in.
        :param username: String, the username to be checked.
        :return: Bool, true if the user is signed in, false if the user does not exist or is not signed in.
        >>> signInSystem.check_sign_in("jack")
        false
        >>> signInSystem.add_user("jack")
        >>> signInSystem.check_sign_in("jack")
        false
        >>> signInSystem.sign_in("jack")
        >>> signInSystem.check_sign_in("jack")
        true
        */
        let status = users.get(username)
        return status ?? false
    }

    public func all_signed_in(): Bool {
        /*
        Check if all users are signed in.
        :return: Bool, true if all users are signed in, false otherwise.
        >>> signInSystem.add_user("jack")
        true
        >>> signInSystem.sign_in("jack")
        true
        >>> signInSystem.all_signed_in()
        true
        */
        if (users.size == 0) {
            return false
        }
        for (username in users.keys()) {
            if (!users[username]) {
                return false
            }
        }
        return true
    }

    public func all_not_signed_in(): ArrayList<String> {
        /*
        Get a list of usernames that are not signed in.
        :return: ArrayList<String>, a list of usernames that are not signed in.
        >>> signInSystem = SignInSystem()
        >>> signInSystem.add_user("a")
        true
        >>> signInSystem.add_user("b")
        true
        >>> signInSystem.all_not_signed_in()
        ['a', 'b']
        */
        let result = ArrayList<String>()
        for (username in users.keys()) {
            if (!users[username]) {
                result.add(username)
            }
        }
        return result
    }
}

import std.collection.*
import std.random.Random

class Snake {

    var length: Int64
    let SCREEN_WIDTH: Int64
    let SCREEN_HEIGHT: Int64
    let BLOCK_SIZE: Int64
    var positions: ArrayList<ArrayList<Int64>>
    var score: Int64
    var food_position: ArrayList<Int64>

    public init(SCREEN_WIDTH: Int64, SCREEN_HEIGHT: Int64, BLOCK_SIZE: Int64, food_position: ArrayList<Int64>) {
        this.length = 1
        this.SCREEN_WIDTH = SCREEN_WIDTH
        this.SCREEN_HEIGHT = SCREEN_HEIGHT
        this.BLOCK_SIZE = BLOCK_SIZE
        this.positions = ArrayList<ArrayList<Int64>>([ArrayList<Int64>([SCREEN_WIDTH / 2, SCREEN_HEIGHT / 2])])
        this.score = 0
        this.food_position = food_position
    }

    public func move(direction: ArrayList<Int64>): Unit {
        let head = this.positions[0]
        let new_x = head[0] + direction[0]
        let new_y = head[1] + direction[1]
        let new_head = ArrayList<Int64>([new_x, new_y])

        // Check if the snake eats food
        if (new_x == this.food_position[0] && new_y == this.food_position[1]) {
            this.eat_food()
        } else {
            // Normal movement: remove tail, add new head
            this.positions.add(new_head, at: 0)
            this.positions.remove(at: this.positions.size - 1)
        }

        // Check if the snake collides with itself
        for (pos in this.positions[1..this.positions.size]) {
            if (pos[0] == new_x && pos[1] == new_y) {
                this.reset()
                return
            }
        }
    }

    public func random_food_position(): Unit {
        var random = Random()
        var x = 0
        var y = 0
        var valid = false

        while (!valid) {
            x = random.nextInt(0, this.SCREEN_WIDTH)
            y = random.nextInt(0, this.SCREEN_HEIGHT)
            valid = true

            // Ensure food does not spawn on snake
            for (pos in this.positions) {
                if (pos[0] == x && pos[1] == y) {
                    valid = false
                    break
                }
            }
        }

        this.food_position = ArrayList<Int64>([x, y])
    }

    public func reset(): Unit {
        this.length = 1
        this.positions = ArrayList<ArrayList<Int64>>([ArrayList<Int64>([this.SCREEN_WIDTH / 2, this.SCREEN_HEIGHT / 2])])
        this.score = 0
        this.random_food_position()
    }

    public func eat_food(): Unit {
        this.length = this.length + 1
        this.score = this.score + 100
        this.positions.add(ArrayList<Int64>([this.food_position[0], this.food_position[1]]), at: 0)
        this.random_food_position()
    }
}

import std.collection.*
import std.regex.*
import std.unicode.*

class SplitSentence {

    public func split_sentences(sentences_string: String): ArrayList<String> {
        let regex = Regex("Mr\\.|\\.|\\?")
        let parts = regex.split(sentences_string)

        var result = ArrayList<String>()
        var i = 0
        var start = 0

        while (i < parts.size && i + 1 < sentences_string.runes().size) {
            let current_part = parts[i]
            let next_char_index = start + current_part.size
            if (next_char_index < sentences_string.size) {
                let next_char = sentences_string[next_char_index]
                // Check if the delimiter was "." or "?" and followed by space or end
                if ((next_char == '.' || next_char == '?') &&
                    (next_char_index + 1 >= sentences_string.size || 
                     sentences_string[next_char_index + 1] == ' ')) {
                    // Avoid splitting on "Mr."
                    if (!(i > 0 && sentences_string[next_char_index - 2..next_char_index + 1] == "Mr.")) {
                        let sentence = sentences_string[start..next_char_index + 1]
                        result.add(sentence)
                        start = next_char_index + 2 // skip the space
                    }
                }
            }
            i = i + 1
        }

        // Add last part if valid
        if (start < sentences_string.size) {
            let last = sentences_string[start..]
            if (last.trim().size > 0) {
                result.add(last)
            }
        }

        return result
    }

    public func count_words(sentence: String): Int64 {
        let words = sentence.trim().split(" ")
        var count = 0
        for (word in words) {
            let cleaned = word.trim()
            if (cleaned.size > 0) {
                let is_word = true
                for (r in cleaned.runes()) {
                    if (!(r.isLetter())) {
                        // Skip punctuation, numbers, etc.
                        continue
                    }
                }
                if (cleaned.runes().any({r: Rune => r.isLetter()})) {
                    count = count + 1
                }
            }
        }
        return count
    }

    public func process_text_file(sentences_string: String): Int64 {
        let sentences = split_sentences(sentences_string)
        var max_words = 0
        for (sentence in sentences) {
            let word_count = count_words(sentence)
            if (word_count > max_words) {
                max_words = word_count
            }
        }
        return max_words
    }
}

import std.collection.ArrayList
import std.collection.HashMap

class SQLGenerator {

    let table_name: String

    public init(table_name: String) {
        this.table_name = table_name
    }

    public func select(fields!: Option<ArrayList<String>> = None, condition!: Option<String> = None): String {
        let base = "SELECT "
        let fields_str = if (fields ?? None) {
            let fs = fields.getOrThrow()
            let parts = ArrayList<String>()
            for (f in 0..fs.size) {
                parts.add(fs[f])
            }
            String.join(", ", parts)
        } else {
            "*"
        }
        let from_clause = " FROM ${this.table_name}"
        let where_clause = if (condition ?? None) {
            " WHERE ${(condition.getOrThrow())}"
        } else {
            ""
        }
        return "${base}${fields_str}${from_clause}${where_clause};"
    }

    public func insert(data: HashMap<String, String>): String {
        let keys = ArrayList<String>()
        let values = ArrayList<String>()
        for (k in data.keys()) {
            keys.add(k)
            values.add("'${data[k]}'")
        }
        let fields_str = String.join(", ", keys)
        let values_str = String.join(", ", values)
        return "INSERT INTO ${this.table_name} (${fields_str}) VALUES (${values_str});"
    }

    public func update(data: HashMap<String, String>, condition: String): String {
        let sets = ArrayList<String>()
        for (k in data.keys()) {
            sets.add("${k} = '${data[k]}'")
        }
        let set_clause = String.join(", ", sets)
        return "UPDATE ${this.table_name} SET ${set_clause} WHERE ${condition};"
    }

    public func delete(condition: String): String {
        return "DELETE FROM ${this.table_name} WHERE ${condition};"
    }

    public func select_female_under_age(age: Int64): String {
        return "SELECT * FROM ${this.table_name} WHERE age < ${age} AND gender = 'female';"
    }

    public func select_by_age_range(min_age: Int64, max_age: Int64): String {
        return "SELECT * FROM ${this.table_name} WHERE age BETWEEN ${min_age} AND ${max_age};"
    }
}

import std.collection.HashMap
import std.collection.ArrayList

class SQLQueryBuilder {

    public static func select(table: String, columns!: ArrayList<String> = ArrayList<String>(['*']), where_condition!: Option<HashMap<String, String>> = None): String {
        var result = "SELECT "
        for (i in 0..columns.size) {
            result = result + "${columns[i]}"
            if (i < columns.size - 1) {
                result = result + ", "
            }
        }
        result = result + " FROM ${table}"
        if (where_condition != None) {
            let condition_map = where_condition.getOrThrow()
            var first = true
            for (key in condition_map.keys()) {
                let value = condition_map[key]
                if (first) {
                    result = result + " WHERE ${key}='${value}'"
                    first = false
                } else {
                    result = result + " AND ${key}='${value}'"
                }
            }
        }
        return result
    }

    public static func insert(table: String, data: HashMap<String, String>): String {
        var columns = ""
        var values = ""
        var first = true
        for (key in data.keys()) {
            let value = data[key]
            if (!first) {
                columns = columns + ", "
                values = values + ", "
            }
            columns = columns + key
            values = values + "'${value}'"
            first = false
        }
        return "INSERT INTO ${table} (${columns}) VALUES (${values})"
    }

    public static func delete(table: String, where_condition!: Option<HashMap<String, String>> = None): String {
        var result = "DELETE FROM ${table}"
        if (where_condition != None) {
            let condition_map = where_condition.getOrThrow()
            var first = true
            for (key in condition_map.keys()) {
                let value = condition_map[key]
                if (first) {
                    result = result + " WHERE ${key}='${value}'"
                    first = false
                } else {
                    result = result + " AND ${key}='${value}'"
                }
            }
        }
        return result
    }

    public static func update(table: String, data: HashMap<String, String>, where_condition!: Option<HashMap<String, String>> = None): String {
        var set_parts = ""
        var first = true
        for (key in data.keys()) {
            let value = data[key]
            if (!first) {
                set_parts = set_parts + ", "
            }
            set_parts = set_parts + "${key}='${value}'"
            first = false
        }
        var result = "UPDATE ${table} SET ${set_parts}"
        if (where_condition != None) {
            let condition_map = where_condition.getOrThrow()
            var first_cond = true
            for (key in condition_map.keys()) {
                let value = condition_map[key]
                if (first_cond) {
                    result = result + " WHERE ${key}='${value}'"
                    first_cond = false
                } else {
                    result = result + " AND ${key}='${value}'"
                }
            }
        }
        return result
    }
}

import std.collection.ArrayList
import std.collection.HashMap
import std.math.abs
import std.sort.sort
import std.math.sqrt

class Statistics3 {

    public static func median(data: ArrayList<Int64>): Float64 {
        if (data.size == 0) {
            return 0.0
        }
        var sorted = ArrayList<Int64>(data)
        sort(sorted)
        let n = sorted.size
        if (n % 2 == 0) {
            return (sorted[n / 2 - 1] + sorted[n / 2]) / 2.0
        } else {
            return sorted[n / 2] as Float64
        }
    }

    public static func mode(data: ArrayList<Int64>): ArrayList<Int64> {
        if (data.size == 0) {
            return ArrayList<Int64>([])
        }
        let freq = HashMap<Int64, Int64>()
        var maxCount = 0
        for (value in data) {
            let count = (freq.get(value) ?? 0) + 1
            freq.add(value, count)
            if (count > maxCount) {
                maxCount = count
            }
        }
        let modes = ArrayList<Int64>()
        for ((value, count) in freq) {
            if (count == maxCount) {
                modes.add(value)
            }
        }
        sort(modes)
        return modes
    }

    public static func mean(data: ArrayList<Int64>): Option<Float64> {
        if (data.size == 0) {
            return None<Float64>
        }
        var sum = 0L
        for (value in data) {
            sum += value
        }
        return Some(sum as Float64 / data.size)
    }

    public static func standard_deviation(data: ArrayList<Int64>): Option<Float64> {
        let meanOpt = Statistics3.mean(data)
        if (meanOpt == None<Float64>) {
            return None<Float64>
        }
        let meanVal = meanOpt.getOrThrow()
        if (data.size == 0) {
            return None<Float64>
        }
        var sumSquaredDiff = 0.0
        for (value in data) {
            let diff = value as Float64 - meanVal
            sumSquaredDiff += diff * diff
        }
        let variance = sumSquaredDiff / data.size
        return Some(sqrt(variance))
    }

    public static func correlation(x: ArrayList<Int64>, y: ArrayList<Int64>): Option<Float64> {
        if (x.size != y.size || x.size == 0) {
            return None<Float64>
        }
        let meanXOpt = Statistics3.mean(x)
        let meanYOpt = Statistics3.mean(y)
        if (meanXOpt == None<Float64> || meanYOpt == None<Float64>) {
            return None<Float64>
        }
        let meanX = meanXOpt.getOrThrow()
        let meanY = meanYOpt.getOrThrow()
        var sumCov = 0.0
        var sumVarX = 0.0
        var sumVarY = 0.0
        for (i in 0..x.size) {
            let diffX = x[i] as Float64 - meanX
            let diffY = y[i] as Float64 - meanY
            sumCov += diffX * diffY
            sumVarX += diffX * diffX
            sumVarY += diffY * diffY
        }
        if (sumVarX == 0.0 || sumVarY == 0.0) {
            return None<Float64>
        }
        let corr = sumCov / sqrt(sumVarX * sumVarY)
        return Some(corr)
    }

    public static func correlation_matrix(data: ArrayList<ArrayList<Int64>>): ArrayList<ArrayList<Float64>> {
        if (data.size == 0) {
            return ArrayList<ArrayList<Float64>>()
        }
        let n = data.size
        let corrMat = ArrayList<ArrayList<Float64>>()
        for (i in 0..n) {
            let row = ArrayList<Float64>()
            for (j in 0..n) {
                let corr = Statistics3.correlation(data[i], data[j])
                if (corr == None<Float64>) {
                    row.add(0.0)
                } else {
                    row.add(corr.getOrThrow())
                }
            }
            corrMat.add(row)
        }
        return corrMat
    }

    public static func z_score(data: ArrayList<Int64>): Option<ArrayList<Float64>> {
        let meanOpt = Statistics3.mean(data)
        let stdOpt = Statistics3.standard_deviation(data)
        if (meanOpt == None<Float64> || stdOpt == None<Float64>) {
            return None<ArrayList<Float64>>
        }
        let meanVal = meanOpt.getOrThrow()
        let stdVal = stdOpt.getOrThrow()
        if (stdVal == 0.0) {
            return None<ArrayList<Float64>>
        }
        let zScores = ArrayList<Float64>()
        for (value in data) {
            zScores.add((value as Float64 - meanVal) / stdVal)
        }
        return Some(zScores)
    }
}

