class StockPortfolioTracker {

    var portfolio: ArrayList<Stock>
    var cash_balance: Float64

    public init(cash_balance: Float64) {
        this.portfolio = ArrayList<Stock>()
        this.cash_balance = cash_balance
    }

    public func add_stock(stock: Stock): Unit {
        this.portfolio.add(stock)
    }

    public func remove_stock(stock: Stock): Bool {
        for (i in 0..this.portfolio.size) {
            if (this.portfolio[i] == stock) {
                this.portfolio.remove(at: i)
                return true
            }
        }
        return false
    }

    public func buy_stock(stock: Stock): Bool {
        let total_cost = stock.price * stock.quantity
        if (this.cash_balance < total_cost) {
            return false
        }
        this.cash_balance = this.cash_balance - total_cost
        this.add_stock(stock)
        return true
    }

    public func sell_stock(stock: Stock): Bool {
        for (i in 0..this.portfolio.size) {
            let held_stock = this.portfolio[i]
            if (held_stock.name == stock.name && held_stock.price == stock.price) {
                if (held_stock.quantity < stock.quantity) {
                    return false
                }
                let sale_value = stock.price * stock.quantity
                this.cash_balance = this.cash_balance + sale_value
                held_stock.quantity = held_stock.quantity - stock.quantity
                if (held_stock.quantity == 0) {
                    this.portfolio.remove(at: i)
                }
                return true
            }
        }
        return false
    }

    public func calculate_portfolio_value(): Float64 {
        var total = 0.0
        for (stock in this.portfolio) {
            total = total + (stock.price * stock.quantity)
        }
        return total + this.cash_balance
    }

    public func get_portfolio_summary(): (Float64, ArrayList<HashMap<String, Any>>) {
        let total_value = this.calculate_portfolio_value()
        let summary = ArrayList<HashMap<String, Any>>()
        for (stock in this.portfolio) {
            let stock_value = stock.price * stock.quantity
            let stock_info = HashMap<String, Any>([("name", stock.name), ("value", stock_value)])
            summary.add(stock_info)
        }
        return (total_value, summary)
    }

    public func get_stock_value(stock: Stock): Float64 {
        return stock.price * stock.quantity
    }
}

