class TriCalculator {

    /*
    The class allows to calculate trigonometric values, including cosine, sine, and tangent, using Taylor series approximations.
    */

    let PI = 3.1415926

    public init() {}

    public func cos(x: Float64): Float64 {
        let radian = x * PI / 180.0
        return taylor(radian, 50)
    }

    public func factorial(a: Int64): Decimal {
        if (a < 0) {
            return Decimal(0)
        }
        var result = Decimal(1)
        for (i in 1..a+1) {
            result = result * Decimal(i)
        }
        return result
    }

    public func taylor(x: Float64, n: Int64): Float64 {
        var result: Float64 = 0.0
        for (i in 0..n+1) {
            let term_index = i * 2
            let sign = if (i % 2 == 0) { 1.0 } else { -1.0 }
            let power = pow(x, term_index)
            let fact = factorial(term_index)
            let term = sign * power.toF64() / fact.toF64()
            result = result + term
        }
        return result
    }

    public func sin(x: Float64): Float64 {
        let radian = x * PI / 180.0
        var result: Float64 = 0.0
        for (i in 0..50) {
            let term_index = i * 2 + 1
            let sign = if (i % 2 == 0) { 1.0 } else { -1.0 }
            let power = pow(radian, term_index)
            let fact = factorial(term_index)
            let term = sign * power.toF64() / fact.toF64()
            result = result + term
        }
        return result
    }

    public func tan(x: Float64): Option<Float64> {
        let cos_val = cos(x)
        if (abs(cos_val - 0.0) < 0.000001) {
            return None<Float64>
        } else {
            return Some<Float64>(sin(x) / cos_val)
        }
    }
}

