class Parser {

    let expr: String
    var pos: Int64
    var ch: Rune

    public init(expr: String) {
        this.expr = expr
        this.pos = -1
        this.ch = r'x'
        this.next_char()
    }

    public func next_char(): Unit {
        this.pos += 1
        if (this.pos < this.expr.size) {
            this.ch = Rune(this.expr[this.pos])
        } else {
            this.ch = r'x'
        }
    }

    public func eat(char_to_eat: Rune): Bool {
        while (this.ch == r' ') {
            this.next_char()
        }
        if (this.ch == char_to_eat) {
            this.next_char()
            return true
        }
        return false
    }

    public func parse(): Int64 {
        let x = this.parse_expression()
        if (this.pos < this.expr.size) {
            throw Exception("Unexpected: ${this.ch}")
        }
        return x
    }

    public func parse_expression(): Int64 {
        var x = this.parse_term()
        while (true) {
            if (this.eat(r'+')) {
                x += this.parse_term()
            } else if (this.eat(r'-')) {
                x -= this.parse_term()
            } else {
                return x
            }
        }
        return x
    }

    public func parse_term(): Int64 {
        var x = this.parse_factor()
        while (true) {
            if (this.eat(r'*')) {
                x *= this.parse_factor()
            } else if (this.eat(r'/')) {
                x /= this.parse_factor()
            } else {
                return x
            }
        }
        return x
    }

    public func parse_factor(): Int64 {
        if (this.eat(r'+')) {
            return this.parse_factor()
        }
        if (this.eat(r'-')) {
            return -this.parse_factor()
        }

        var x = 0
        var start_pos = this.pos

        if (this.eat(r'(')) {
            x = this.parse_expression()
            this.eat(r')')
        } else if (this.ch != r'x' && (this.ch.isAsciiNumber() || this.ch == r'.')) {
            while (this.ch != r'x' && (this.ch.isAsciiNumber() || this.ch == r'.')) {
                this.next_char()
            }
            x = Int64.parse(this.expr[start_pos..this.pos])
        } else {
            if (this.ch != r'x') {
                throw Exception("Unexpected: ${this.ch}")
            } else {
                throw Exception("Unexpected end of expression")
            }
        }
        return x
    }
}

class TwentyFourPointGame {

    var nums: ArrayList<Int64>

    public init() {
        this.nums = ArrayList<Int64>()
    }

    public func _generate_cards(): Unit {
        let rand = Random()
        this.nums.clear()
        for (i in 0..4) {
            this.nums.add(rand.nextInt(1, 10))
        }
    }

    public func get_my_cards(): ArrayList<Int64> {
        this._generate_cards()
        return this.nums
    }

    public func answer(expression: String): Bool {
        return this.evaluate_expression(expression)
    }

    public func evaluate_expression(expression: String): Bool {
        // Check if all characters are valid
        for (c in expression.runes()) {
            if (c != r' ' && c != r'+' && c != r'-' && c != r'*' && c != r'/' && c != r'(' && c != r')' && !c.isAsciiNumber()) {
                return false
            }
        }

        // Parse expression
        try {
            let parser = Parser(expression)
            let result = parser.parse()
            return result == 24
        } catch (_) {
            return false
        }
    }
}

import std.collection.HashMap

class URLHandler {

    let url: String

    public init(url: String) {
        this.url = url
    }

    public func get_scheme(): Option<String> {
        let scheme_end = url.find("://")
        if (scheme_end.isSome()) {
            return Some<String>(url[0..scheme_end.getOrThrow()])
        }
        return None<String>
    }

    public func get_host(): Option<String> {
        let scheme_end = url.find("://")
        var start = 0
        if (scheme_end.isSome()) {
            start = scheme_end.getOrThrow() + 3
        }
        let rest = url[start..]
        let host_end = match (rest.find("/")) {
            case Some<Int64>(pos) => pos
            case Some<Int64>(_) if (rest.find("?").isSome() && rest.find("?").getOrThrow() < pos) => rest.find("?").getOrThrow()
            case Some<Int64>(_) if (rest.find("#").isSome() && rest.find("#").getOrThrow() < pos) => rest.find("#").getOrThrow()
            case None<Int64> => rest.find("?").isSome() ? rest.find("?").getOrThrow() : rest.find("#").getOrThrowOr(-1)
        }
        if (host_end == -1) {
            return Some<String>(rest)
        }
        return Some<String>(rest[0..host_end])
    }

    public func get_path(): Option<String> {
        let scheme_end = url.find("://")
        var start = 0
        if (scheme_end.isSome()) {
            start = scheme_end.getOrThrow() + 3
        }
        let rest = url[start..]
        let host_end = match (rest.find("/")) {
            case Some<Int64>(pos) => pos
            case None<Int64> => return None<String>
        }
        return Some<String>(rest[host_end..])
    }

    public func get_query_params(): Option<HashMap<String, String>> {
        let q_start = url.find("?")
        if (q_start.isNone()) {
            return None<HashMap<String, String>>
        }
        let frag_start = url.find("#")
        let end = if (frag_start.isSome()) { frag_start.getOrThrow() } else { url.size }
        let query_str = url[q_start.getOrThrow() + 1 .. end]
        let pairs = query_str.split("&")
        let params = HashMap<String, String>()
        for (pair in pairs) {
            let kv = pair.split("=")
            if (kv.size == 2) {
                params.add(kv[0], kv[1])
            }
        }
        return Some<HashMap<String, String>>(params)
    }

    public func get_fragment(): Option<String> {
        let frag_start = url.find("#")
        if (frag_start.isNone()) {
            return None<String>
        }
        let start = frag_start.getOrThrow() + 1
        if (start >= url.size) {
            return None<String>
        }
        return Some<String>(url[start..])
    }
}

import std.collection.ArrayList

class UrlPath {

    /*
    The  class is a utility for encapsulating and manipulating the path component of a URL, including adding nodes, parsing path strings, and building path strings with optional encoding.
    */

    let segments: ArrayList<String>
    var with_end_tag: Bool

    public init() {
        /*
        Initializes the UrlPath object with an empty list of segments and a flag indicating the presence of an end tag.
        */
        this.segments = ArrayList<String>()
        this.with_end_tag = false
    }

    public func add(segment: String): Unit {
        /*
        Adds a segment to the list of segments in the UrlPath.
        :param segment: String, the segment to add.
        >>> url_path = UrlPath()
        >>> url_path.add('foo')
        >>> url_path.add('bar')

        url_path.segments = ['foo', 'bar']
        */
        this.segments.add(segment)
    }

    public func parse(path: String): Unit {
        /*
        Parses a given path string and populates the list of segments in the UrlPath.
        :param path: String, the path string to parse.
        >>> url_path = UrlPath()
        >>> url_path.parse('/foo/bar/')

        url_path.segments = ['foo', 'bar']
        */
        let fixed_path = UrlPath::fix_path(path)
        if (fixed_path == "") {
            return
        }
        let parts = fixed_path.split("/")
        for (part in 0..parts.size) {
            let segment = parts[part]
            if (segment != "") {
                this.segments.add(segment)
            }
        }
        this.with_end_tag = path.endsWith("/")
    }

    public static func fix_path(path: String): String {
        /*
        Fixes the given path string by removing leading and trailing slashes.
        :param path: String, the path string to fix.
        :return: String, the fixed path string.
        >>> url_path = UrlPath()
        >>> url_path.fix_path('/foo/bar/')
        'foo/bar'

        */
        let start = if (path.startsWith("/")) { 1 } else { 0 }
        let end = if (path.endsWith("/")) { path.size - 1 } else { path.size }
        return path[start..end]
    }
}

import std.collection.HashMap
import std.collection.ArrayList
import std.math.abs
import std.math.sqrt
import std.math.log
import std.math.pow

class VectorUtil {

    public static func similarity(vector_1: ArrayList<Float64>, vector_2: ArrayList<Float64>): Float64 {
        let dim = vector_1.size
        var dot_product: Float64 = 0.0
        var norm1_sq: Float64 = 0.0
        var norm2_sq: Float64 = 0.0

        for (i in 0..dim) {
            dot_product += vector_1[i] * vector_2[i]
            norm1_sq += vector_1[i] * vector_1[i]
            norm2_sq += vector_2[i] * vector_2[i]
        }

        let norm1 = sqrt(norm1_sq)
        let norm2 = sqrt(norm2_sq)

        if (norm1 == 0.0 || norm2 == 0.0) {
            return 0.0
        }

        return dot_product / (norm1 * norm2)
    }

    public static func cosine_similarities(vector_1: ArrayList<Float64>, vectors_all: ArrayList<ArrayList<Float64>>): ArrayList<Float64> {
        let result = ArrayList<Float64>()
        let n = vectors_all.size

        for (i in 0..n) {
            let sim = similarity(vector_1, vectors_all[i])
            result.add(sim, at: i)
        }

        return result
    }

    public static func n_similarity(vector_list_1: ArrayList<ArrayList<Float64>>, vector_list_2: ArrayList<ArrayList<Float64>>): Float64 {
        let avg_vector_1 = compute_mean_vector(vector_list_1)
        let avg_vector_2 = compute_mean_vector(vector_list_2)
        return similarity(avg_vector_1, avg_vector_2)
    }

    private static func compute_mean_vector(vectors: ArrayList<ArrayList<Float64>>): ArrayList<Float64> {
        if (vectors.size == 0) {
            return ArrayList<Float64>()
        }

        let dim = vectors[0].size
        let mean_vector = ArrayList<Float64>(ArrayList<Float64>([0.0] * dim))
        let n = vectors.size

        for (i in 0..dim) {
            var sum: Float64 = 0.0
            for (j in 0..n) {
                sum += vectors[j][i]
            }
            mean_vector[i] = sum / n.toFloat64()
        }

        return mean_vector
    }

    public static func compute_idf_weight_dict(total_num: Int64, number_dict: HashMap<String, Float64>): HashMap<String, Float64> {
        let result = HashMap<String, Float64>()
        for (entry in number_dict) {
            let key = entry.key
            let count = entry.value
            let weight = log((total_num + 1).toFloat64() / (count + 1).toFloat64())
            result.add(key, weight)
        }
        return result
    }
}

import std.collection.HashMap
import std.collection.ArrayList

class Product <: Equatable<Product> {

    let price: Float64
    var quantity: Int64

    public init(price: Float64, quantity: Int64) {
        this.price = price
        this.quantity = quantity
    }

    public override operator func != (that: Product): Bool {
        return this.price != that.price || this.quantity != that.quantity
    }

    public override operator func == (that: Product): Bool {
        return this.price == that.price && this.quantity == that.quantity
    }
}

class VendingMachine {

    var inventory: HashMap<String, Product>
    var balance: Float64

    public init() {
        this.inventory = HashMap<String, Product>()
        this.balance = 0.0
    }

    public func add_item(item_name: String, price: Float64, quantity: Int64): Unit {
        let product = Product(price, quantity)
        this.inventory.add(item_name, product)
    }

    public func insert_coin(amount: Float64): Float64 {
        this.balance = this.balance + amount
        return this.balance
    }

    public func purchase_item(item_name: String): Option<Float64> {
        if (this.inventory.contains(item_name)) {
            let product = this.inventory[item_name]
            if (product.quantity > 0 && this.balance >= product.price) {
                product.quantity = product.quantity - 1
                this.balance = this.balance - product.price
                return Some<Float64>(this.balance)
            }
        }
        return None<Float64>
    }

    public func restock_item(item_name: String, quantity: Int64): Bool {
        if (this.inventory.contains(item_name)) {
            let product = this.inventory[item_name]
            product.quantity = product.quantity + quantity
            return true
        }
        return false
    }

    public func display_items(): Option<String> {
        if (this.inventory.size == 0) {
            return None<String>
        }
        var result = ""
        for (key in this.inventory.keys().toArrayList()) {
            let product = this.inventory[key]
            result = result + "${key} - $${product.price} [${product.quantity}]"
        }
        return Some<String>(result)
    }
}

