class Warehouse {

    let inventory: HashMap<Int64, Product>
    let orders: HashMap<Int64, Order>

    public init() {
        this.inventory = HashMap<Int64, Product>()
        this.orders = HashMap<Int64, Order>()
    }

    public func add_product(product_id: Int64, name: String, quantity: Int64): Unit {
        match (this.inventory.get(product_id)) {
            case Some<Product>(p) => {
                p.quantity = p.quantity + quantity
            }
            case None<Product> => {
                let product = Product(name, quantity)
                this.inventory.add(product_id, product)
            }
        }
    }

    public func update_product_quantity(product_id: Int64, quantity: Int64): Unit {
        match (this.inventory.get(product_id)) {
            case Some<Product>(p) => {
                p.quantity = p.quantity + quantity
            }
            case None<Product> => {}
        }
    }

    public func get_product_quantity(product_id: Int64): Option<Int64> {
        match (this.inventory.get(product_id)) {
            case Some<Product>(p) => Some<Int64>(p.quantity)
            case None<Product> => None<Int64>
        }
    }

    public func create_order(order_id: Int64, product_id: Int64, quantity: Int64): Bool {
        match (this.inventory.get(product_id)) {
            case Some<Product>(p) if p.quantity >= quantity => {
                let order = Order(product_id, quantity, "Shipped")
                this.orders.add(order_id, order)
                p.quantity = p.quantity - quantity
                return true
            }
            case _ => {
                return false
            }
        }
    }

    public func change_order_status(order_id: Int64, status: String): Bool {
        match (this.orders.get(order_id)) {
            case Some<Order>(o) => {
                o.status = status
                return true
            }
            case None<Order> => {
                return false
            }
        }
    }

    public func track_order(order_id: Int64): Option<String> {
        match (this.orders.get(order_id)) {
            case Some<Order>(o) => Some<String>(o.status)
            case None<String> => None<String>
        }
    }
}

